insert into public.fiches (id, theme, vignette, titre, resume, intro, sections, ordre) values
  ('anxiete', 'Anxiété', 0, 'Anxiété', 'Comprendre l’anxiété et la calmer au quotidien.', 'L’anxiété est une réaction normale du corps face à ce qu’il perçoit comme un danger. Elle nous prépare à agir. Elle devient un problème quand elle revient trop souvent, qu’elle dure ou qu’elle prend trop de place dans ta journée.', '[{"titre":"Ce qui peut se passer","paragraphes":["Dans la tête, l’anxiété prend souvent la forme d’inquiétudes difficiles à arrêter : on imagine le pire, on a l’impression que quelque chose de grave va arriver, on tourne en boucle sur les mêmes pensées.","Le corps suit. Le cœur s’accélère, le souffle devient court, les épaules et la mâchoire se crispent. Beaucoup de femmes remarquent aussi un sommeil plus léger ou des réveils au milieu de la nuit. Ces sensations sont désagréables, mais elles ne sont pas dangereuses et finissent toujours par redescendre."]},{"titre":"Ce qui peut aider sur le moment","paragraphes":["La respiration est l’outil le plus rapide. Inspire lentement pendant 5 secondes, puis expire pendant 5 secondes, et recommence pendant quelques minutes. En ralentissant ton souffle, tu envoies à ton corps le signal que tout va bien. L’exercice « Respirer » de l’app te guide pas à pas.","Tu peux aussi revenir au moment présent avec l’ancrage 5-4-3-2-1 : nomme 5 choses que tu vois, 4 que tu peux toucher, 3 que tu entends, 2 odeurs que tu sens et 1 goût dans ta bouche. Cet exercice occupe ton attention et coupe le fil des pensées anxieuses.","Quand l’inquiétude se calme un peu, écris-la. Puis pose-toi deux questions : quelle est la probabilité réelle que cela arrive ? Et que dirais-je à une amie qui vivrait la même chose ? Souvent, on est bien plus douce avec les autres qu’avec soi-même."]},{"titre":"Au quotidien","paragraphes":["Certaines habitudes entretiennent l’anxiété sans qu’on s’en rende compte. Le café, le thé fort, les boissons énergisantes et l’alcool peuvent l’augmenter : essaie de les réduire, surtout l’après-midi.","Bouger chaque jour aide aussi beaucoup. Pas besoin de sport intense : une marche de vingt minutes suffit à faire baisser la tension. Enfin, des horaires de sommeil réguliers rendent le corps plus solide face au stress.","Si l’anxiété t’empêche de vivre normalement, de travailler ou de dormir, parles-en à une médecin ou à une psychologue. L’anxiété se soigne très bien."]}]'::jsonb, 1),
  ('depression', 'Humeur', 2, 'Humeur basse et dépression', 'Repérer les signes et faire de petits pas.', 'Tout le monde traverse des jours sans énergie ni envie. Mais quand la tristesse s’installe et ne repart pas, il peut s’agir d’une dépression. Ce n’est ni de la paresse ni un manque de volonté : c’est une maladie, et elle se soigne.', '[{"titre":"Les signes à surveiller","paragraphes":["La dépression se manifeste souvent par une tristesse ou une sensation de vide présente la plupart du temps, et par une perte d’intérêt pour ce qui faisait plaisir avant. Les journées semblent lourdes, même les choses simples demandent un effort.","Le corps est touché lui aussi : fatigue persistante, appétit ou sommeil qui changent, difficulté à se concentrer. Beaucoup de femmes ressentent aussi de la culpabilité ou l’impression de ne rien valoir.","Si ces signes durent depuis plus de deux semaines, parles-en à une médecin ou à une psychologue. Demander de l’aide n’est pas un aveu de faiblesse, c’est le premier pas vers le mieux."]},{"titre":"Avancer à petits pas","paragraphes":["Quand l’énergie manque, les grands objectifs découragent. Choisis plutôt une seule petite action par jour, agréable ou utile : prendre une douche, sortir dix minutes, appeler une personne que tu aimes.","Fais-la même sans en avoir envie. Avec l’humeur basse, l’envie revient souvent après l’action, rarement avant. Chaque petit pas compte, même s’il paraît insignifiant.","Le soir, note dans ton journal ce que tu as fait et comment tu t’es sentie ensuite. Avec le temps, ces notes te montreront ce qui t’aide vraiment."]},{"titre":"Si tu as des pensées sombres","paragraphes":["Si tu penses à la mort ou à te faire du mal, ne reste pas seule avec ces pensées. Ouvre l’onglet SOS et appelle un numéro d’aide, ou parle tout de suite à une personne de confiance. Tu mérites d’être aidée maintenant."]}]'::jsonb, 2),
  ('travail', 'Travail', 3, 'Stress au travail', 'Prévenir l’épuisement et poser des limites.', 'Un peu de pression peut motiver. Mais quand le stress devient permanent, il use le corps et le moral, jusqu’à l’épuisement. Le repérer tôt permet d’agir avant de tomber.', '[{"titre":"Les signes d’alerte","paragraphes":["Le premier signe est souvent une fatigue qui ne passe plus, même après un week-end ou des congés. On se lève déjà épuisée, avec l’impression de ne jamais récupérer.","Peu à peu, une distance s’installe avec le travail : on devient cynique, on se sent moins efficace, on doute de ses compétences. L’irritabilité augmente, le sommeil se dégrade, et les maux de tête ou de ventre deviennent fréquents."]},{"titre":"Reprendre de l’air","paragraphes":["Les vraies pauses font une grande différence. Environ toutes les heures et demie, accorde-toi quelques minutes loin de l’écran : marcher, boire un verre d’eau, regarder dehors.","Le soir, fixe-toi une heure de fin de journée et un petit rituel pour marquer la coupure : fermer l’ordinateur, changer de tenue, sortir marcher. Ton esprit a besoin de savoir que la journée de travail est terminée.","Quand tout semble urgent, fais la liste de tes tâches et classe-les : ce qui est vraiment urgent, ce qui est important mais peut attendre, et ce qui pourrait être confié à quelqu’un d’autre ou refusé."]},{"titre":"Poser des limites","paragraphes":["Dire non est difficile, surtout quand on a peur de décevoir. Pourtant, une limite posée calmement est souvent bien reçue. Tu peux dire par exemple : « Je ne peux pas prendre ce dossier cette semaine, mais je peux m’en occuper la semaine prochaine. »","Si la pression ne baisse pas, parles-en à ta médecin, et si c’est possible à ta hiérarchie ou aux ressources humaines. Un arrêt de travail est parfois nécessaire pour récupérer : ce n’est pas un échec, c’est un soin."]}]'::jsonb, 3),
  ('sommeil', 'Sommeil', 4, 'Sommeil', 'Des habitudes simples pour mieux dormir.', 'Le sommeil et le moral sont étroitement liés : quand on dort mal, tout paraît plus lourd, et quand on est inquiète, on dort mal. Quelques habitudes simples peuvent aider à casser ce cercle.', '[{"titre":"Un rythme régulier","paragraphes":["Ton corps fonctionne avec une horloge interne. Pour la régler, le plus efficace est de te lever à la même heure chaque jour, même le week-end, même après une mauvaise nuit. L’heure du coucher suivra plus facilement.","Le soir, essaie de laisser les écrans de côté trente à soixante minutes avant de dormir. Leur lumière et ce qu’ils nous font lire gardent le cerveau en éveil."]},{"titre":"Quand le sommeil ne vient pas","paragraphes":["Si tu ne dors toujours pas au bout d’une vingtaine de minutes, ne reste pas à te tourner dans ton lit. Lève-toi, fais une activité calme sous une lumière douce, puis retourne te coucher quand tu sens le sommeil revenir.","Si ce sont tes pensées qui te tiennent éveillée, prends l’habitude de les écrire sur papier avant de te coucher. Les poser quelque part aide ta tête à les lâcher pour la nuit."]}]'::jsonb, 4),
  ('charge-mentale', 'Charge mentale', 1, 'Charge mentale', 'Quand tout repose sur toi.', 'La charge mentale, c’est le fait de penser, prévoir et organiser en permanence pour les autres : la maison, les enfants, la famille élargie, le travail. Même quand quelqu’un d’autre fait les tâches, c’est souvent toi qui dois y penser. Ce n’est pas un manque d’organisation, c’est un poids réel, souvent invisible.', '[{"titre":"Rendre visible ce qui ne se voit pas","paragraphes":["Une grande partie de la charge mentale vient du fait qu’elle reste dans ta tête. Prends un moment pour écrire tout ce à quoi tu penses : les courses, les rendez-vous, les anniversaires, les factures, les devoirs des enfants. Mettre ces choses sur papier soulage déjà, et rend le partage possible."]},{"titre":"Partager vraiment","paragraphes":["Partager ne veut pas dire seulement déléguer des tâches ponctuelles. Le plus efficace est de confier des domaines entiers, comme les repas de la semaine ou le suivi de l’école : la personne qui s’en charge doit y penser ET le faire, sans attendre tes rappels.","Cela demande d’accepter que certaines choses soient faites autrement que toi. Ce n’est pas toujours facile, mais c’est le prix de ta tranquillité d’esprit."]},{"titre":"Garder un temps pour toi","paragraphes":["Enfin, réserve chaque semaine un moment qui n’appartient qu’à toi, même court. Ce n’est pas un luxe ni de l’égoïsme : c’est ce qui te permet de continuer à prendre soin des autres sans t’oublier."]}]'::jsonb, 5),
  ('hormones', 'Cycle', 5, 'Cycle, grossesse et humeur', 'Les étapes hormonales peuvent influencer le moral.', 'Les hormones ne font pas tout, mais elles jouent sur l’humeur à plusieurs moments de la vie d’une femme. Les connaître aide à mieux comprendre ce que tu ressens, et à savoir quand demander de l’aide.', '[{"titre":"Avant les règles","paragraphes":["Dans les jours qui précèdent les règles, certaines femmes ressentent une humeur très basse, de l’irritabilité ou de l’anxiété. Quand ces symptômes sont intenses au point de gêner la vie quotidienne, on parle de trouble dysphorique prémenstruel. C’est un vrai trouble, et il se traite."]},{"titre":"Après un accouchement","paragraphes":["La dépression post-partum est fréquente. Elle peut apparaître dans les semaines qui suivent la naissance, mais aussi plusieurs mois après. Elle ne signifie en aucun cas un manque d’amour pour ton bébé. En parler à une sage-femme ou à une médecin permet d’être accompagnée et de se sentir mieux."]},{"titre":"Autour de la ménopause","paragraphes":["Pendant la périménopause, les années qui précèdent la ménopause, les hormones varient beaucoup. Cela peut entraîner de l’anxiété, des troubles du sommeil et une humeur changeante, parfois difficile à comprendre pour soi comme pour l’entourage."]},{"titre":"Ce que tu peux faire","paragraphes":["Noter ton humeur chaque jour dans ton journal t’aidera à repérer un éventuel lien avec ton cycle. Ces notes sont précieuses : montre-les à ta médecin, ta gynécologue ou ta sage-femme, elles l’aideront à te proposer la bonne solution."]}]'::jsonb, 6);
insert into public.pensees (texte, ordre) values
  ('Une émotion n’est pas un fait. Elle passe, comme une vague.', 1),
  ('Te reposer n’est pas de la paresse : c’est une condition pour continuer.', 2),
  ('Parle-toi comme tu parlerais à ta meilleure amie.', 3),
  ('Bois un verre d’eau et regarde par la fenêtre pendant une minute.', 4),
  ('Demander de l’aide est un signe de force, pas de faiblesse.', 5),
  ('Fais une seule chose à la fois aujourd’hui, autant que possible.', 6),
  ('Tu n’as pas besoin de tout régler aujourd’hui.', 7);
insert into public.idees_recues (affirmation, explication, ordre) values
  ('La dépression, c’est juste de la fatigue. Il suffit de se reposer.', 'La dépression est une maladie, pas un manque de volonté ni de repos. Elle se soigne, et en parler à une professionnelle est un vrai premier pas.', 1),
  ('Voir une psychologue, c’est réservé aux personnes « folles ».', 'Consulter, c’est prendre soin de sa santé, comme on le fait pour le corps. Beaucoup de femmes consultent pour du stress, un deuil ou un épuisement.', 2),
  ('Une bonne mère ne se sent jamais dépassée.', 'Se sentir dépassée arrive à toutes les mères. Le reconnaître et demander du soutien protège ta santé et celle de ta famille.', 3),
  ('Si je parle de mes difficultés, je vais embêter les autres.', 'Partager ce que tu vis renforce souvent les liens. Tu as le droit d’avoir besoin des autres, comme ils ont parfois besoin de toi.', 4);
insert into public.contacts_sos (pays, nom, numero, description, principal, ordre) values
  ('BJ', 'SAMU', '112', 'Urgence médicale, gratuit', true, 0),
  ('BJ', 'Police', '117', 'Gratuit, 24 h/24, 7 j/7', false, 1),
  ('BJ', 'Sapeurs-pompiers', '118', 'Gratuit, 24 h/24, 7 j/7', false, 2),
  ('BJ', 'Institut national de la femme', '01 51 07 88 88', 'Alerte violences faites aux femmes', false, 3);
insert into public.sena_etapes (id, messages, choix) values
  ('debut', '["Je suis là pour t’écouter, sans jugement.","Comment te sens-tu en ce moment ?"]'::jsonb, '[{"label":"Stressée, débordée","action":{"type":"etape","vers":"stress"}},{"label":"Triste, sans énergie","action":{"type":"etape","vers":"triste"}},{"label":"Anxieuse","action":{"type":"etape","vers":"anxieuse"}},{"label":"En colère","action":{"type":"etape","vers":"colere"}},{"label":"Ça va plutôt bien","action":{"type":"etape","vers":"bien"}},{"label":"J’ai des idées noires","action":{"type":"etape","vers":"danger"}}]'::jsonb),
  ('stress', '["Ça fait beaucoup à porter. Quand tout s’accumule, la tête et le corps finissent par saturer.","Tu veux qu’on souffle ensemble 2 minutes, ou qu’on essaie de mettre de l’ordre dans ce qui t’occupe l’esprit ?"]'::jsonb, '[{"label":"Souffler 2 minutes","action":{"type":"respirer"}},{"label":"Faire le tri","action":{"type":"etape","vers":"tri"}},{"label":"Lire sur la charge mentale","action":{"type":"fiche","id":"charge-mentale"}}]'::jsonb),
  ('tri', '["Prends une minute pour écrire tout ce que tu as en tête, sans trier : le travail, la maison, la famille, les petites choses aussi.","Ensuite, choisis une seule chose à faire aujourd’hui. Le reste peut attendre, ou être confié à quelqu’un d’autre.","Tu veux l’écrire dans ton journal ?"]'::jsonb, '[{"label":"Ouvrir mon journal","action":{"type":"journal"}},{"label":"Merci, ça m’aide","action":{"type":"etape","vers":"fin"}}]'::jsonb),
  ('triste', '["Merci de me le dire. Se sentir triste ou vidée, c’est lourd, et tu n’as pas à faire semblant ici.","Parfois, un tout petit pas aide : boire un verre d’eau, ouvrir une fenêtre, envoyer un message à une personne de confiance.","Si cette tristesse dure depuis plus de deux semaines, parles-en à une médecin ou à une psychologue. Ce n’est pas une faiblesse."]'::jsonb, '[{"label":"Noter mon humeur","action":{"type":"journal"}},{"label":"Lire sur l’humeur basse","action":{"type":"fiche","id":"depression"}},{"label":"C’est plus grave que ça","action":{"type":"etape","vers":"danger"}}]'::jsonb),
  ('anxieuse', '["L’anxiété peut faire battre le cœur vite et emballer les pensées. Ça va passer, même si ça ne semble pas comme ça maintenant.","On essaie un exercice pour revenir au moment présent ?"]'::jsonb, '[{"label":"Oui, guide-moi","action":{"type":"etape","vers":"ancrage"}},{"label":"Plutôt respirer","action":{"type":"respirer"}},{"label":"Lire sur l’anxiété","action":{"type":"fiche","id":"anxiete"}}]'::jsonb),
  ('ancrage', '["Regarde autour de toi et nomme 5 choses que tu vois.","Maintenant, 4 choses que tu peux toucher. Sens leur texture.","3 sons que tu entends, proches ou lointains.","2 odeurs, même légères.","Et 1 goût dans ta bouche.","Comment te sens-tu maintenant ?"]'::jsonb, '[{"label":"Un peu mieux","action":{"type":"etape","vers":"mieux"}},{"label":"Toujours pareil","action":{"type":"etape","vers":"pareil"}}]'::jsonb),
  ('mieux', '["Je suis contente que ça t’aide. Tu peux revenir faire cet exercice quand tu veux."]'::jsonb, '[{"label":"Noter mon humeur","action":{"type":"journal"}},{"label":"Parler d’autre chose","action":{"type":"etape","vers":"debut"}}]'::jsonb),
  ('pareil', '["C’est normal, ça ne marche pas à chaque fois du premier coup.","Respirer lentement peut aider le corps à se calmer."]'::jsonb, '[{"label":"Souffler 2 minutes","action":{"type":"respirer"}},{"label":"J’ai besoin d’aide maintenant","action":{"type":"etape","vers":"danger"}}]'::jsonb),
  ('colere', '["La colère dit souvent qu’une limite a été dépassée. Tu as le droit de la ressentir.","Avant de répondre ou d’agir, ça peut aider de laisser redescendre la pression quelques minutes."]'::jsonb, '[{"label":"Souffler 2 minutes","action":{"type":"respirer"}},{"label":"Écrire ce que je ressens","action":{"type":"journal"}},{"label":"Lire : poser des limites","action":{"type":"fiche","id":"travail"}}]'::jsonb),
  ('bien', '["Ça fait plaisir à lire ! Qu’est-ce qui t’a fait du bien aujourd’hui ?","Le noter dans ton journal t’aidera à t’en souvenir les jours plus difficiles."]'::jsonb, '[{"label":"Ouvrir mon journal","action":{"type":"journal"}},{"label":"Parler d’autre chose","action":{"type":"etape","vers":"debut"}}]'::jsonb),
  ('danger', '["Merci de me l’avoir dit. Ce que tu ressens compte, et tu mérites d’être aidée tout de suite.","Je ne suis pas une thérapeute, mais des personnes peuvent t’aider maintenant. Si tu es en danger, appelle le SAMU (112) ou la police (117).","Si tu le peux, appelle aussi une personne de confiance et ne reste pas seule."]'::jsonb, '[{"label":"Appeler le 112","action":{"type":"appel","numero":"112"}},{"label":"Voir les numéros d’aide","action":{"type":"sos"}}]'::jsonb),
  ('texteLibre', '["Merci de me l’avoir confié.","Je ne comprends pas encore tout ce qu’on m’écrit. Pour t’aider au mieux, dis-moi ce qui ressemble le plus à ce que tu vis :"]'::jsonb, '[{"label":"Stressée, débordée","action":{"type":"etape","vers":"stress"}},{"label":"Triste, sans énergie","action":{"type":"etape","vers":"triste"}},{"label":"Anxieuse","action":{"type":"etape","vers":"anxieuse"}},{"label":"En colère","action":{"type":"etape","vers":"colere"}},{"label":"Ça va plutôt bien","action":{"type":"etape","vers":"bien"}},{"label":"J’ai des idées noires","action":{"type":"etape","vers":"danger"}}]'::jsonb),
  ('fin', '["Avec plaisir. Je suis là quand tu veux."]'::jsonb, '[{"label":"Parler d’autre chose","action":{"type":"etape","vers":"debut"}}]'::jsonb);
